"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { ClerkFailed, ClerkLoaded, ClerkLoading, HandleSSOCallback, TaskChooseOrganization, TaskResetPassword, TaskSetupMFA, useSession } from "@clerk/nextjs";
import { authRoute } from "@/lib/auth-navigation";

export function AuthCallback({ destination }: { destination: string }) {
  const [slow, setSlow] = useState(false);
  useEffect(() => { const timer = setTimeout(() => setSlow(true), 15000); return () => clearTimeout(timer); }, []);
  return <div className="auth-content">
    <span className="auth-overline">ONE MOMENT</span><h1>Let’s get you settled.</h1>
    <ClerkLoading><p className="auth-description" role="status">Loading secure sign-in.</p></ClerkLoading>
    <ClerkFailed><p className="auth-status auth-error" role="alert">We couldn’t connect to sign-in. Your draft stays on this device.</p></ClerkFailed>
    <ClerkLoaded><ResolveCallback destination={destination}/></ClerkLoaded>
    {slow && <p className="auth-status" role="status">Taking longer than expected? Return to sign-in and try again. Any saved draft stays on this device.</p>}
    <Link className="auth-recovery" href={authRoute("/sign-in", destination)}>Back to sign-in</Link>
  </div>;
}

function ResolveCallback({ destination }: { destination: string }) {
  const { session } = useSession();
  if (session?.currentTask) {
    const task = session.currentTask.key;
    const props = { redirectUrlComplete: destination };
    if (task === "choose-organization") return <TaskChooseOrganization {...props}/>;
    if (task === "reset-password") return <TaskResetPassword {...props}/>;
    if (task === "setup-mfa") return <TaskSetupMFA {...props}/>;
    return <p className="auth-status auth-error" role="alert">Your account needs an additional setup step. Return to sign-in to complete it.</p>;
  }
  return <>
    <p className="auth-description" role="status">Finishing your Google sign-in. You’ll return to {destination === "/new" ? "your idea" : "your research"}.</p>
    <HandleSSOCallback
      navigateToApp={({ session: activeSession, decorateUrl }) => {
        const target = activeSession?.currentTask ? authRoute("/sso-callback", destination) : destination;
        window.location.assign(decorateUrl(target));
      }}
      navigateToSignIn={() => window.location.assign(authRoute("/sign-in", destination, true))}
      navigateToSignUp={() => window.location.assign(authRoute("/sign-up", destination, true))}
    />
  </>;
}
import Link from "next/link";
import localFont from "next/font/local";
import { LoaderCircle } from "lucide-react";
import { GoogleAuth } from "./google-auth";
import { authRoute } from "@/lib/auth-navigation";

export type AuthMode = "sign-in" | "sign-up";
const googleFont = localFont({
  src: "../app/fonts/GoogleSans-Medium.ttf",
  weight: "500",
  display: "swap",
});

export function GoogleButtonFace({ busy = false }: { busy?: boolean }) {
  return (
    <>
      {busy ? (
        <LoaderCircle size={20} className="spinner" aria-hidden="true" />
      ) : (
        <img src="/auth/google-g.png" width="20" height="20" alt="" />
      )}
      <span className={googleFont.className}>Continue with Google</span>
    </>
  );
}

export function AuthLoading() {
  return (
    <div className="auth-content">
      <h1>Welcome back.</h1>
      <p className="auth-description">Sign in to explore your idea.</p>
      <button className="google-button" disabled aria-busy="true">
        <GoogleButtonFace busy />
      </button>
    </div>
  );
}

export function AuthContent({
  mode,
  configured,
  destination,
  verify = false,
}: {
  mode: AuthMode;
  configured: boolean;
  destination: string;
  verify?: boolean;
}) {
  const signup = mode === "sign-up";
  const alternate = authRoute(signup ? "/sign-in" : "/sign-up", destination);
  return (
    <div className="auth-content">
      <h1>
        {signup ? (
          <>
            Your next idea
            <br />
            starts here.
          </>
        ) : (
          "Welcome back."
        )}
      </h1>
      <p className="auth-description">
        {signup
          ? "Create your Hunchlane account to keep your research and return to your ideas."
          : "Sign in to explore your idea."}
      </p>
      {configured ? (
        <GoogleAuth
          mode={mode}
          destination={destination}
          verify={verify}
          button={<GoogleButtonFace />}
          busyButton={<GoogleButtonFace busy />}
        />
      ) : (
        <div>
          <button
            className="google-button"
            disabled
            aria-describedby="auth-unavailable"
          >
            <GoogleButtonFace />
          </button>
          <p
            className="auth-status auth-error"
            id="auth-unavailable"
            role="status"
          >
            Sign-in is being connected. Your draft stays on this device.
          </p>
          <Link className="auth-recovery" href="/sample">
            Explore the sample report <span aria-hidden="true">↗</span>
          </Link>
        </div>
      )}
      {signup && (
        <p className="auth-switch">
          Already have an account? <Link href={alternate}>Sign in</Link>
        </p>
      )}
    </div>
  );
}
"use client";

import { useEffect, useRef, useState } from "react";
import { CircleHelp, LoaderCircle, ArrowRight } from "lucide-react";
import type { AgentQuestion } from "@/core/agent";

export function AgentQuestionCard({ question, index, total, busy, onAnswer, onAutoAnswer }: {
  question: AgentQuestion;
  index: number;
  total: number;
  busy: boolean;
  onAnswer: (text: string) => void;
  onAutoAnswer: () => void;
}) {
  const [selected, setSelected] = useState<string[]>([]);
  const [custom, setCustom] = useState("");
  const [ownAnswer, setOwnAnswer] = useState(false);
  const title = useRef<HTMLLegendElement>(null);
  const customInput = useRef<HTMLTextAreaElement>(null);
  useEffect(() => { title.current?.focus({preventScroll:true}); }, [question.id]);
  useEffect(() => {
    if (ownAnswer) customInput.current?.focus();
  }, [ownAnswer]);
  const answer = [...selected, ...(ownAnswer && custom.trim() ? [custom.trim()] : [])].join("; ");
  return (
    <form className="agent-question-card" onSubmit={event => {
      event.preventDefault();
      if (answer && answer.length <= 500 && !busy) onAnswer(answer);
    }}>
      <div className="agent-question-card-heading"><CircleHelp size={16} />Agent has questions for you</div>
      <div className="agent-question-card-body">
        <fieldset disabled={busy}>
          <legend ref={title} tabIndex={-1}>{question.text}</legend>
          <div className="agent-question-options">
            {question.suggestions.map(option => (
              <label className="agent-question-option" key={option}>
                <input type="checkbox" checked={selected.includes(option)} onChange={event => setSelected(current => event.target.checked ? [...current, option] : current.filter(value => value !== option))} />
                <span>{option}</span>
              </label>
            ))}
            <label className="agent-question-option">
              <input type="checkbox" checked={ownAnswer} onChange={event => setOwnAnswer(event.target.checked)} />
              <span>Something else</span>
            </label>
            {ownAnswer && <textarea ref={customInput} aria-label="Your own answer" value={custom} maxLength={500} rows={2} onChange={event => setCustom(event.target.value)} placeholder="Tell us in your own words…" />}
          </div>
        </fieldset>
        {answer.length > 500 && <p role="status" className="chat-subtle">Keep your combined answer within 500 characters.</p>}
        <div className="agent-question-card-footer">
          <span>Question {index + 1} of {total}</span>
          <div>
            <button type="button" className="agent-auto-answer" aria-label="Auto-answer remaining questions" disabled={busy} onClick={onAutoAnswer}>Auto-answer</button>
            <button type="submit" className="agent-question-next" disabled={busy || !answer || answer.length > 500}>
              {busy ? <LoaderCircle size={16} className="spinner" /> : <>Next <ArrowRight size={14} /></>}
            </button>
          </div>
        </div>
      </div>
    </form>
  );
}

