.auth-story-foot{margin-top:36px;display:flex;align-items:center;gap:8px;color:#526e5d;font-size:10px}
.auth-panel{display:flex;align-items:center;justify-content:center;padding:52px 56px;min-width:0}
.auth-content{width:100%;max-width:380px}
.auth-overline{display:block;color:#65766c;font-size:9px;font-weight:650;letter-spacing:1.5px;margin-bottom:18px}
.auth-content h1{font-family:inherit;font-size:40px;line-height:1.16;letter-spacing:-1.6px;font-weight:600;color:#23332e}
.auth-description{color:#627268;font-size:14px;line-height:1.7;margin:16px 0 30px}
.google-button{display:flex;align-items:center;justify-content:center;gap:10px;min-height:52px;width:100%;padding:12px;border:1px solid #747775;border-radius:12px;background:#fff;color:#1f1f1f;font-size:15px;font-weight:500;line-height:20px;transition:background-color 140ms,border-color 140ms,box-shadow 140ms,transform 140ms}
.google-button img{flex-shrink:0;object-fit:contain}
.google-button:hover:not(:disabled){background:#f8faf9;box-shadow:0 3px 12px -6px #23332e30}
.google-button:active:not(:disabled){transform:translateY(1px)}
.google-button:disabled{opacity:.65;cursor:default;background:#fbfcfb}
.auth-reassurance{color:#65766b;text-align:center;font-size:11px;line-height:1.7;margin:18px 10px 0}
.auth-status{color:#607366;font-size:12px;line-height:1.7;margin:14px 0 0}
.auth-error{color:#9b392e;padding:12px 14px;border:1px solid #eacdc5;border-radius:10px;background:#fff8f5}
.auth-recovery{display:inline-flex;align-items:center;gap:6px;min-height:44px;padding:8px 0;border:0;background:transparent;color:#175d50;font-size:12px;text-decoration:underline;text-underline-offset:3px}
.auth-switch{text-align:center;font-size:12px;color:#647268;margin:32px 0 0;display:flex;flex-wrap:wrap;gap:4px 6px;align-items:center;justify-content:center}
.auth-switch a{color:#175d50;font-weight:650;display:inline-flex;align-items:center;min-height:44px;text-decoration:underline;text-underline-offset:3px}
.auth-draft{margin-top:28px;padding:16px 18px;border:1px solid #e0e7df;background:#f5f8f4;border-radius:12px}
.auth-draft-label{display:flex;align-items:center;gap:7px;font-size:10px;font-weight:600;color:#52695b}
.auth-draft p{font-size:12px;line-height:1.6;margin:9px 0 2px;overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.auth-draft a{display:inline-flex;align-items:center;gap:6px;color:#175d50;font-size:11px;min-height:44px;text-decoration:underline;text-underline-offset:3px}
.auth-verification{margin:20px -12px}
.auth-verification .cl-rootBox,.auth-verification .cl-cardBox{max-width:100%;width:100%}
.auth-verification .cl-cardBox{box-shadow:none}
